from ansible.module_utils.facts.sysctl import get_sysctl


class FakeModule:
    def __init__(self, result=None, error=None):
        self.result = result
        self.error = error
        self.commands = []
        self.warnings = []

    def get_bin_path(self, name):
        assert name == "sysctl"
        return "/sbin/sysctl"

    def run_command(self, command):
        self.commands.append(command)
        if self.error is not None:
            raise self.error
        return self.result

    def warn(self, message):
        self.warnings.append(message)


def test_get_sysctl_parses_blank_multiline_and_delimited_values():
    module = FakeModule(
        result=(
            0,
            "\n"
            "net.ipv4.ip_forward = 1\n"
            " continuation line\n"
            "vm.swappiness: 10\n",
            "",
        )
    )

    result = get_sysctl(module, ["net.ipv4", "vm"])

    assert module.commands == [["/sbin/sysctl", "net.ipv4", "vm"]]
    assert result == {
        "net.ipv4.ip_forward": "1\n continuation line",
        "vm.swappiness": "10",
    }
    assert module.warnings == []


def test_get_sysctl_warns_and_ignores_malformed_lines():
    module = FakeModule(result=(0, "malformed sysctl output\n", ""))

    result = get_sysctl(module, [])

    assert result == {}
    assert len(module.warnings) == 1
    assert module.warnings[0].startswith(
        "Unable to split sysctl line (malformed sysctl output):"
    )


def test_get_sysctl_warns_and_returns_empty_dict_when_command_raises():
    module = FakeModule(error=OSError("permission denied"))

    result = get_sysctl(module, ["kernel"])

    assert module.commands == [["/sbin/sysctl", "kernel"]]
    assert result == {}
    assert module.warnings == ["Unable to read sysctl: permission denied"]


def test_get_sysctl_returns_empty_dict_for_nonzero_command_status():
    module = FakeModule(result=(1, "ignored output\n", "sysctl failed"))

    result = get_sysctl(module, ["kernel"])

    assert module.commands == [["/sbin/sysctl", "kernel"]]
    assert result == {}
    assert module.warnings == []
